	function getSearchRank(rng) {
		$.ajax({
	    	url : '/search/getRank',
	    	data : {range : rng},
	    	type: "GET",
	    	dataType : "json",
	    	async : false,
	    	success : function(data) {
	    		var arr = data.Query;
	    		var hList = "";

	    		for(var i in arr){
	    			if (i < 3) {
	    				hList += '<li class="active">';
	    			} else {
		    			hList += '<li>';
	    			}

		    		hList += '	<a href="#none" onclick="searchText(\''+arr[i].content+'\')">';
		    		hList += '        <span class="num">'+arr[i].id+'</span>'+arr[i].content;

		    		if (arr[i].updown == 'N') {
		    			hList += '        <span class="category new">NEW</span>';
		    		}
		    		if (arr[i].updown == 'C') {
		    			hList += '        <span class="category">-</span>';
		    		}
		    		if (arr[i].updown == 'U') {
		    			hList += '        <span class="category up">'+arr[i].count+'</span>';
		    		}
		    		if (arr[i].updown == 'D') {
		    			hList += '        <span class="category down">'+arr[i].count+'</span>';
		    		}

		    		hList += '    </a>';
		    		hList += '</li>';
			   	}

	    		$('#rankList').html(hList);

	    		if (rng == 'D') {
	    			$('#rankDay').addClass("active");
	    			$('#rankWeek').removeClass("active");
	    		} else {
	    			$('#rankDay').removeClass("active");
	    			$('#rankWeek').addClass("active");
	    		}
	    	}
	    });
	}
</script>

